import java.net.DatagramPacket;
import java.nio.charset.StandardCharsets;

public class Main {
  // Simulates JVM DatagramSocket.receive(packet) truncating to packet.getLength()
  static void simulateReceive(DatagramPacket packet, String incoming) {
    byte[] src = incoming.getBytes(StandardCharsets.UTF_8);
    int count = Math.min(src.length, packet.getLength());
    System.arraycopy(src, 0, packet.getData(), 0, count);
    packet.setLength(count);
  }

  public static void main(String[] args) {
    byte[] buffer = new byte[64];
    DatagramPacket packet = new DatagramPacket(buffer, buffer.length);
    String[] incomingDatagrams = {"HI", "TEMPERATURE 22.5", "OK"};

    for (String msg : incomingDatagrams) {
      // TODO: Reset packet length to buffer.length before receiving!
      simulateReceive(packet, msg);
      String decoded = new String(
          packet.getData(), 0, packet.getLength(), StandardCharsets.UTF_8);
      System.out.println("Received [" + packet.getLength() + "]: " + decoded);
    }
  }
}

